import { Buffer } from "node:buffer";
export default async function upload({ privateKey }, context) {
  if (typeof privateKey !== "string" || !privateKey.trim())
    throw Error("ImageKit private key is required");
  let redirect;
  try {
    redirect = await context.fetch("https://picsum.photos/200/300", { method: "GET" });
  } catch {
    throw Error("Sample image request failed");
  }
  if (redirect.status !== 302) throw Error("Sample image did not return the expected redirect");
  let url;
  try {
    url = new URL(redirect.headers.get("location"));
  } catch {
    throw Error("Sample image redirect is invalid");
  }
  if (
    url.protocol !== "https:" ||
    url.hostname !== "fastly.picsum.photos" ||
    url.port ||
    url.username ||
    url.password ||
    url.hash
  )
    throw Error("Sample image redirect has an unexpected destination");
  let image;
  try {
    image = await context.fetch(url.href, { method: "GET" });
  } catch {
    throw Error("Sample image download failed");
  }
  if (!image.ok || !/^image\/jpeg(?:\s*;|$)/i.test(image.headers.get("content-type") || ""))
    throw Error("Sample image response is not a JPEG");
  const bytes = Buffer.from(await image.arrayBuffer());
  if (
    !bytes.length ||
    bytes[0] !== 255 ||
    bytes[1] !== 216 ||
    bytes[bytes.length - 2] !== 255 ||
    bytes[bytes.length - 1] !== 217
  )
    throw Error("Sample image was incomplete");
  const auth = "Basic " + Buffer.from(privateKey + ":").toString("base64");
  const boundary = "openflow-imagekit-boundary";
  const fields = [
    ["file", bytes.toString("base64")],
    ["fileName", "picsum-image.jpg"],
    ["useUniqueFileName", "true"],
  ];
  const body =
    fields
      .map(
        ([k, v]) => `--${boundary}\r\nContent-Disposition: form-data; name="${k}"\r\n\r\n${v}\r\n`,
      )
      .join("") + `--${boundary}--\r\n`;
  let response;
  try {
    response = await context.fetch("https://upload.imagekit.io/api/v1/files/upload", {
      method: "POST",
      headers: { authorization: auth, "content-type": `multipart/form-data; boundary=${boundary}` },
      body,
    });
  } catch {
    throw Error("ImageKit upload result is unknown; inspect your media library before retrying");
  }
  if (!response.ok)
    throw Error("ImageKit upload failed; inspect your media library before retrying");
  let data;
  try {
    data = await response.json();
  } catch {
    throw Error("ImageKit upload response was invalid; inspect your media library before retrying");
  }
  if (typeof data?.fileId !== "string" || !data.fileId)
    throw Error("ImageKit returned no file ID; inspect your media library before retrying");
  return { fileId: data.fileId };
}
